nginx_config:
daemon off;
master_process on;
worker_processes 4;
pid /tmp/aegisx-bench-16j3v418/nginx.pid;
error_log /tmp/aegisx-bench-16j3v418/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-16j3v418/body;
    proxy_temp_path /tmp/aegisx-bench-16j3v418/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 127.0.0.1:59841; keepalive 256; }
    server {
        listen 127.0.0.1:45165 reuseport;
        location / {
            root /tmp/aegisx-bench-16j3v418/site;
            open_file_cache max=1000 inactive=60s;
            open_file_cache_valid 1s;
        }
    }
}
